mapper.sql:
 FROM asset a
 JOIN asset_assignment aa ON aa.company_id = a.company_id AND aa.asset_id = a.asset_id
WHERE a.company_id = #{companyId}
  AND aa.employee_id = #{employeeId}
  AND aa.returned_at IS NULL
  AND a.status_code = 'AS_IN_USE'

mapper.select:
SELECT asset_assignment_id AS assetAssignmentId, asset_id AS assetId,
       it_ticket_id AS itTicketId, issued_at AS issuedAt, returned_at AS returnedAt
  FROM asset_assignment
 WHERE company_id = #{companyId}
   AND employee_id = #{employeeId}
   AND asset_id = #{assetId}
 ORDER BY issued_at DESC, asset_assignment_id DESC
